Here's a complete, self-contained Account Settings screen using only core React Native APIs (no extra dependencies needed), so it works out of the box on both iOS and Android.

```tsx
// AccountSettingsScreen.tsx
import React, { useCallback, useState } from 'react';
import {
  Alert,
  Image,
  Platform,
  SafeAreaView,
  ScrollView,
  StyleSheet,
  Switch,
  Text,
  TouchableOpacity,
  View,
} from 'react-native';

type NavRow = {
  id: string;
  type: 'nav';
  label: string;
  value?: string;
  onPress: () => void;
};

type SwitchRow = {
  id: string;
  type: 'switch';
  label: string;
  value: boolean;
  onValueChange: (value: boolean) => void;
};

type SettingsRowData = NavRow | SwitchRow;

type Section = {
  id: string;
  title: string;
  rows: SettingsRowData[];
};

interface User {
  name: string;
  email: string;
  avatarUrl?: string;
}

const CURRENT_USER: User = {
  name: 'Jordan Lee',
  email: 'jordan.lee@example.com',
  avatarUrl: undefined,
};

function getInitials(name: string): string {
  return name
    .split(' ')
    .filter(Boolean)
    .map((part) => part[0]?.toUpperCase())
    .slice(0, 2)
    .join('');
}

const ProfileRow: React.FC<{ user: User; onPress: () => void }> = ({ user, onPress }) => (
  <TouchableOpacity
    style={styles.profileRow}
    onPress={onPress}
    accessibilityRole="button"
    accessibilityLabel={`Edit profile for ${user.name}`}
  >
    {user.avatarUrl ? (
      <Image source={{ uri: user.avatarUrl }} style={styles.avatar} />
    ) : (
      <View style={[styles.avatar, styles.avatarFallback]}>
        <Text style={styles.avatarInitials}>{getInitials(user.name)}</Text>
      </View>
    )}
    <View style={styles.profileText}>
      <Text style={styles.profileName}>{user.name}</Text>
      <Text style={styles.profileEmail}>{user.email}</Text>
    </View>
    <Text style={styles.chevron}>›</Text>
  </TouchableOpacity>
);

const SettingsRow: React.FC<{ row: SettingsRowData; isLast: boolean }> = ({ row, isLast }) => {
  if (row.type === 'switch') {
    return (
      <View style={[styles.row, isLast && styles.rowLast]}>
        <Text style={styles.rowLabel}>{row.label}</Text>
        <Switch value={row.value} onValueChange={row.onValueChange} />
      </View>
    );
  }

  return (
    <TouchableOpacity
      style={[styles.row, isLast && styles.rowLast]}
      onPress={row.onPress}
      accessibilityRole="button"
      accessibilityLabel={row.label}
    >
      <Text style={styles.rowLabel}>{row.label}</Text>
      <View style={styles.rowRight}>
        {row.value ? <Text style={styles.rowValue}>{row.value}</Text> : null}
        <Text style={styles.chevron}>›</Text>
      </View>
    </TouchableOpacity>
  );
};

const SectionBlock: React.FC<{ section: Section }> = ({ section }) => (
  <View style={styles.section}>
    <Text style={styles.sectionTitle}>{section.title}</Text>
    <View style={styles.sectionCard}>
      {section.rows.map((row, index) => (
        <SettingsRow key={row.id} row={row} isLast={index === section.rows.length - 1} />
      ))}
    </View>
  </View>
);

const AccountSettingsScreen: React.FC = () => {
  const [pushEnabled, setPushEnabled] = useState(true);
  const [faceIdEnabled, setFaceIdEnabled] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const handleEditProfile = useCallback(() => {
    // Navigate to profile edit screen.
    console.log('Navigate to edit profile');
  }, []);

  const handleChangePassword = useCallback(() => {
    console.log('Navigate to change password');
  }, []);

  const handleManageDevices = useCallback(() => {
    console.log('Navigate to manage devices');
  }, []);

  const handleHelpCenter = useCallback(() => {
    console.log('Navigate to help center');
  }, []);

  const handleContactSupport = useCallback(() => {
    console.log('Navigate to contact support');
  }, []);

  const performAccountDeletion = useCallback(async () => {
    setIsDeleting(true);
    try {
      // await api.deleteAccount();
      await new Promise((resolve) => setTimeout(resolve, 1200));
      Alert.alert('Account deleted', 'Your account has been permanently deleted.');
      // Navigate to a signed-out/auth screen here.
    } catch (error) {
      Alert.alert('Something went wrong', 'We could not delete your account. Please try again.');
    } finally {
      setIsDeleting(false);
    }
  }, []);

  const handleDeleteAccount = useCallback(() => {
    Alert.alert(
      'Delete account',
      'This will permanently delete your account and all associated data. This action cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: performAccountDeletion,
        },
      ],
      { cancelable: true },
    );
  }, [performAccountDeletion]);

  const sections: Section[] = [
    {
      id: 'account',
      title: 'Account',
      rows: [
        { id: 'password', type: 'nav', label: 'Change password', onPress: handleChangePassword },
        { id: 'devices', type: 'nav', label: 'Manage devices', onPress: handleManageDevices },
        {
          id: 'faceid',
          type: 'switch',
          label: Platform.OS === 'ios' ? 'Face ID' : 'Fingerprint unlock',
          value: faceIdEnabled,
          onValueChange: setFaceIdEnabled,
        },
      ],
    },
    {
      id: 'notifications',
      title: 'Notifications',
      rows: [
        {
          id: 'push',
          type: 'switch',
          label: 'Push notifications',
          value: pushEnabled,
          onValueChange: setPushEnabled,
        },
      ],
    },
    {
      id: 'support',
      title: 'Support',
      rows: [
        { id: 'help', type: 'nav', label: 'Help center', onPress: handleHelpCenter },
        { id: 'contact', type: 'nav', label: 'Contact support', onPress: handleContactSupport },
      ],
    },
  ];

  return (
    <SafeAreaView style={styles.safeArea}>
      <ScrollView
        style={styles.container}
        contentContainerStyle={styles.contentContainer}
        contentInsetAdjustmentBehavior="automatic"
      >
        <Text style={styles.screenTitle}>Account Settings</Text>

        <ProfileRow user={CURRENT_USER} onPress={handleEditProfile} />

        {sections.map((section) => (
          <SectionBlock key={section.id} section={section} />
        ))}

        <View style={styles.section}>
          <TouchableOpacity
            style={styles.deleteRow}
            onPress={handleDeleteAccount}
            disabled={isDeleting}
            accessibilityRole="button"
            accessibilityLabel="Delete account"
            accessibilityState={{ disabled: isDeleting }}
          >
            <Text style={styles.deleteLabel}>
              {isDeleting ? 'Deleting account…' : 'Delete account'}
            </Text>
          </TouchableOpacity>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: '#F2F2F7',
  },
  container: {
    flex: 1,
  },
  contentContainer: {
    paddingBottom: 40,
  },
  screenTitle: {
    fontSize: 28,
    fontWeight: '700',
    color: '#111111',
    paddingHorizontal: 16,
    paddingTop: Platform.select({ ios: 12, android: 20 }),
    paddingBottom: 12,
  },
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: '#FFFFFF',
    marginHorizontal: 16,
    borderRadius: 12,
    padding: 16,
    marginBottom: 24,
    ...Platform.select({
      ios: {
        shadowColor: '#000000',
        shadowOpacity: 0.05,
        shadowRadius: 4,
        shadowOffset: { width: 0, height: 2 },
      },
      android: {
        elevation: 1,
      },
    }),
  },
  avatar: {
    width: 56,
    height: 56,
    borderRadius: 28,
    backgroundColor: '#E5E5EA',
  },
  avatarFallback: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  avatarInitials: {
    fontSize: 20,
    fontWeight: '600',
    color: '#636366',
  },
  profileText: {
    flex: 1,
    marginLeft: 14,
  },
  profileName: {
    fontSize: 17,
    fontWeight: '600',
    color: '#111111',
  },
  profileEmail: {
    fontSize: 14,
    color: '#8E8E93',
    marginTop: 2,
  },
  section: {
    marginBottom: 24,
    paddingHorizontal: 16,
  },
  sectionTitle: {
    fontSize: 13,
    fontWeight: '600',
    color: '#8E8E93',
    textTransform: 'uppercase',
    marginBottom: 8,
    marginLeft: 4,
  },
  sectionCard: {
    backgroundColor: '#FFFFFF',
    borderRadius: 12,
    overflow: 'hidden',
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingVertical: 14,
    paddingHorizontal: 16,
    borderBottomWidth: 1,
    borderBottomColor: '#E5E5EA',
    minHeight: 48,
  },
  rowLast: {
    borderBottomWidth: 0,
  },
  rowLabel: {
    fontSize: 16,
    color: '#111111',
  },
  rowRight: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  rowValue: {
    fontSize: 16,
    color: '#8E8E93',
    marginRight: 6,
  },
  chevron: {
    fontSize: 20,
    color: '#C7C7CC',
  },
  deleteRow: {
    backgroundColor: '#FFFFFF',
    borderRadius: 12,
    paddingVertical: 14,
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: 48,
  },
  deleteLabel: {
    fontSize: 16,
    fontWeight: '600',
    color: '#FF3B30',
  },
});

export default AccountSettingsScreen;
```

Notes on the choices:

- **Delete confirmation** uses `Alert.alert` with a `destructive` style button on the "Delete" action — this renders the native iOS red-destructive style and the standard Android dialog, and is the idiomatic cross-platform confirmation pattern (no custom modal needed).
- The delete row disables itself and shows a "Deleting…" label while the async call is in flight, so a user can't double-submit.
- No external icon/UI libraries are used, so this drops into any RN project without extra install steps. Swap the `›` chevrons for a vector-icon library if your app already has one.
- Accessibility roles/labels are set on interactive rows for screen reader support (VoiceOver/TalkBack) on both platforms.
